// Own: zzOWN.com - Own Fast. Work Faster.  | Ema: zzown.com@gmail.com
// Des: Typed errors, exit codes, what-why-fix messages
// Flo: error set > map error to exit code 0-4 > map error to 3-line message
// I/O: anyerror (caller) > u8 exit code + Mesg (stderr text)
// ===================================================================
const std = @import("std");
const CF = .{ .okay = 0, .fail = 1, .usag = 2, .drif = 3, .bloc = 4 };
pub const Erro = error{ BadUsage, BadConfig, Drift, Halted, CapHit, QuietHour, NeedApprove, NeedLogin, Paused, NoBrowser, BrowFail, Timeout, Closed, TooBig, BadFrame, BadHandshake, CdpError, EvalFail, NoElement, NoJob, Dupe, NavFail, SqliOpen, SqliExec, SqliPrep, SqliBind, SqliStep, AiFail, Fail };
pub const Mesg = struct { what: []const u8, whyz: []const u8, fixz: []const u8 };
pub fn exitCode(erro: anyerror) u8 { return switch (erro) { error.BadUsage, error.NoJob, error.BadConfig => CF.usag, error.Drift, error.NoElement => CF.drif, error.Halted, error.CapHit, error.QuietHour, error.NeedApprove, error.NeedLogin, error.Paused => CF.bloc, else => CF.fail }; }
pub fn mesg(erro: anyerror) Mesg { return switch (erro) { error.BadUsage => .{ .what = "bad usage", .whyz = "unknown command or flag", .fixz = "run: fb help" }, error.NoJob => .{ .what = "unknown job", .whyz = "no such job name", .fixz = "run: fb help" }, error.BadConfig => .{ .what = "bad config", .whyz = "aa-conf-main.json has a bad value", .fixz = "fix the key or delete the file for defaults" }, error.Drift => .{ .what = "page changed", .whyz = "the page does not look as expected", .fixz = "run: fb status, then check the labels in config" }, error.Halted => .{ .what = "stopped by Facebook", .whyz = "checkpoint, captcha, 2FA, warning or block seen", .fixz = "open Facebook yourself, clear it, then run: fb login" }, error.CapHit => .{ .what = "daily limit reached", .whyz = "this action hit its cap for now", .fixz = "wait, or raise the capz_* key in aa-conf-main.json (slowly)" }, error.QuietHour => .{ .what = "quiet hours", .whyz = "no activity during quiet hours", .fixz = "run later, or change quie_hour_rang" }, error.NeedApprove => .{ .what = "needs your approval", .whyz = "risky action (new person, friend request, delete)", .fixz = "re-run with --live --force after checking the preview" }, error.NeedLogin => .{ .what = "not logged in", .whyz = "Facebook shows a login page", .fixz = "run: fb login, log in by hand in the window" }, error.Paused => .{ .what = "paused", .whyz = "pause or stop flag is set", .fixz = "run: fb resume" }, error.NoBrowser => .{ .what = "no browser", .whyz = "Chrome or Edge not found", .fixz = "install Chrome, or set brow_exec_path" }, error.BrowFail => .{ .what = "browser failed", .whyz = "the browser did not start or closed", .fixz = "close other windows using the fb profile, retry" }, error.Timeout => .{ .what = "timeout", .whyz = "no answer in time", .fixz = "retry; raise brow_time_seco if it repeats" }, error.NoElement => .{ .what = "button or box not found", .whyz = "label not on the page", .fixz = "check labl_* in aa-conf-main.json for your language" }, error.Dupe => .{ .what = "already done", .whyz = "same action was done before", .fixz = "nothing to do" }, error.AiFail => .{ .what = "AI unavailable", .whyz = "Claude CLI and llama.cpp both failed", .fixz = "set smar_mode_enab false or fix the AI tool" }, else => .{ .what = "failed", .whyz = @errorName(erro), .fixz = "re-run with --json and check status" } }; }
